// Launchpad phone app: offline copy. Generated by tools/build_phone.py; the cache name changes with every build.
const CACHE = 'launchpad-d8ce30e9ed';
const FILES = ['./', './index.html', './manifest.webmanifest', './icon-192.png', './icon-512.png', './icon-maskable-512.png', './apple-touch-icon.png'];
self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('launchpad-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // GitHub API calls always go to the network
  if (req.mode === 'navigate') {
    // Try for a fresh copy (so updates arrive), but don't wait more than 3 seconds on a slow connection.
    const fresh = fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put('./index.html', copy)); }
      return res;
    });
    const slow = new Promise((resolve) => setTimeout(resolve, 3000));
    event.respondWith(Promise.race([fresh.catch(() => null), slow])
      .then((res) => res || caches.match('./index.html'))
      .then((res) => res || fresh));
    return;
  }
  event.respondWith(caches.match(req).then((hit) => hit || fetch(req)));
});
